    $admin = auth('admin')->user();
    $permissions = app(\App\Http\Middleware\Permission::class);
    $canUse = fn (string $route): bool => $permissions->allows($admin, $route);
    $canUpdateSettings = $canUse('site.settings.update');
    $canResetSettings = $canUse('site.settings.destroy');
    $isSettingsViewOnly = !$canUpdateSettings && !$canResetSettings;
    $ui = fn (string $key, array $replace = []): string => \App\Support\AdminUi::text('customizer.'.$key, $replace);
    $toolCards = [
        ['route' => 'page.index', 'label' => $ui('tools.content_hub'), 'description' => $ui('tools.content_hub_help'), 'icon' => 'fa-file-text-o', 'url' => route('page.index')],
        ['route' => 'site.settings.index', 'label' => $ui('tools.design'), 'description' => $ui('tools.design_help'), 'icon' => 'fa-paint-brush', 'url' => route('site.settings.index', ['locale' => $locale]).'#settings-design'],
        ['route' => 'site.settings.index', 'label' => $ui('tools.donation'), 'description' => $ui('tools.donation_help'), 'icon' => 'fa-heart-o', 'url' => route('site.settings.index', ['locale' => $locale]).'#settings-donation_page'],
        ['route' => 'page.menu.index', 'label' => $ui('tools.navigation'), 'description' => $ui('tools.navigation_help'), 'icon' => 'fa-sitemap', 'url' => route('page.menu.index')],
        ['route' => 'media.index', 'label' => $ui('tools.media'), 'description' => $ui('tools.media_help'), 'icon' => 'fa-picture-o', 'url' => route('media.index')],
        ['route' => 'reusable-blocks.index', 'label' => $ui('tools.reusable'), 'description' => $ui('tools.reusable_help'), 'icon' => 'fa-clone', 'url' => route('reusable-blocks.index')],
        ['route' => 'seo.index', 'label' => $ui('tools.search'), 'description' => $ui('tools.search_help'), 'icon' => 'fa-search', 'url' => route('seo.index')],
        ['route' => 'content.trash.index', 'label' => $ui('tools.trash'), 'description' => $ui('tools.trash_help'), 'icon' => 'fa-trash', 'url' => route('content.trash.index')],
    ];
    $toolCards = array_values(array_filter($toolCards, fn (array $tool): bool => $canUse($tool['route'])));
    $previewPages = [
        $ui('preview_pages.home') => route('frontend.home', ['lang' => $locale]),
        $ui('preview_pages.contact') => route('frontend.contactUs', ['lang' => $locale]),
