        density:{compact:{'--igf-header-utility-height':'34px','--igf-header-nav-height':'70px','--igf-header-nav-height-mobile':'64px'},standard:{'--igf-header-utility-height':'38px','--igf-header-nav-height':'80px','--igf-header-nav-height-mobile':'70px'},spacious:{'--igf-header-utility-height':'44px','--igf-header-nav-height':'92px','--igf-header-nav-height-mobile':'78px'}},
