ter-badge-bg':'rgba(255,177,116,.14)','--igf-footer-badge-text':'#ffc99f','--igf-footer-success-bg':'rgba(38,129,68,.28)','--igf-footer-success-border':'rgba(119,221,151,.55)','--igf-footer-success-text':'#d9fbe3','--igf-footer-error-bg':'rgba(176,51,40,.3)','--igf-footer-error-border':'rgba(255,138,128,.65)','--igf-footer-error-text':'#ffe1de'}},
        layout:{columns:{'--igf-footer-shell-width':'1440px','--igf-footer-body-columns':'minmax(220px,.9fr) minmax(0,2.1fr)','--igf-footer-body-legal-columns':'minmax(250px,.85fr) minmax(0,3.15fr)','--igf-footer-body-tablet-columns':'minmax(240px,.82fr) minmax(0,1.8fr)','--igf-footer-content-legal-columns':'minmax(0,2.1fr) minmax(300px,1fr)','--igf-footer-content-tablet-columns':'repeat(2,minmax(0,1fr))'},stacked:{'--igf-footer-shell-width':'1100px','--igf-footer-body-columns':'1fr','--igf-footer-body-legal-columns':'1fr','--igf-footer-body-tablet-columns':'1fr','--igf-footer-content-legal-columns':'1fr','--igf-footer-content-tablet-columns':'1fr'}}
    };
    function newFaqItemMarkup(){return `<article class="customizer-faq-item" data-faq-item><header class="customizer-faq-item__head"><strong data-faq-number>${escapeHtml(copy.faq.new)}</strong><div class="customizer-faq-item__actions"><button type="button" data-faq-move="up" aria-label="${escapeHtml(copy.faq.move_up_generic)}"><i class="fa fa-arrow-up" aria-hidden="true"></i></button><button type="button" data-faq-move="down" aria-label="${escapeHtml(copy.faq.move_down_generic)}"><i class="fa fa-arrow-down" aria-hidden="true"></i></button><button class="is-danger" type="button" data-faq-remove aria-label="${escapeHtml(copy.faq.remove_generic)}"><i class="fa fa-trash" aria-hidden="true"></i></button></div></header><div class="customizer-faq-fields"><div class="customizer-faq-field"><label data-faq-label="question">${escapeHtml(copy.faq.question)}</label><input type="text" maxlength="500" data-faq-field="question"></div><div class="customizer-faq-field"><label data-faq-label="answer">${escapeHtml(copy.faq.answer)}</label><textarea maxlength="5000" data-faq-field="answer"></textarea></div><div class="customizer-faq-item__visibility"><input type="hidden" value="0" data-faq-field="is_active"><label class="customizer-check" data-faq-label="is_active"><input type="checkbox" value="1" data-faq-field="is_active" checked> ${escapeHtml(copy.faq.show_publicly)}</label></div></div></article>`}
    function updateFaqEditor(editor){const container=editor.querySelector('[data-faq-items]');const items=[...container.querySelectorAll('[data-faq-item]')];const prefix=editor.dataset.faqName;items.forEach((item,index)=>{const number=index+1;item.querySelector('[data-faq-number]').textContent=formatCopy(copy.faq.number,{number});item.querySelectorAll('[data-faq-field]').forEach(control=>{const field=control.dataset.faqField;control.name=`${prefix}[${index}][${field}]`;if(control.type!=='hidden')control.id=`setting-contact_page-faqs-${index}-${field}`});item.querySelectorAll('[data-faq-label]').forEach(label=>{label.htmlFor=`setting-contact_page-faqs-${index}-${label.dataset.faqLabel}`});const up=item.querySelector('[data-faq-move="up"]');const down=item.querySelector('[data-faq-move="down"]');const remove=item.querySelector('[data-faq-remove]');if(up){up.disabled=index===0;up.setAttribute('aria-label',formatCopy(copy.faq.move_up,{number}))}if(down){down.disabled=index===items.length-1;down.setAttribute('aria-label',formatCopy(copy.faq.move_down,{number}))}if(remove)remove.setAttribute('aria-label',formatCopy(copy.faq.remove,{number}))});let empty=container.querySelector('[data-faq-empty]');if(!empty){empty=document.createElement('p');empty.className='customizer-faq-empty';empty.dataset.faqEmpty='';empty.textContent=copy.faq.empty;container.prepend(empty)}empty.hidden=items.length>0;const count=editor.querySelector('[data-faq-count]');if(count)count.textContent=formatCopy(items.length===1?copy.faq.one_question:copy.faq.many_questions,{count:items.length});const add=editor.querySelector('[data-faq-add]');if(add)add.disabled=items.length>=50}
    document.querySelectorAll('[data-faq-editor]').forEach(editor=>{updateFaqEditor(editor);editor.addEventListener('input',()=>setDirty(true));editor.addEventListener('change',()=>setDirty(true));editor.addEventListener('click',event=>{const add=event.target.closest('[data-faq-add]');const item=event.target.closest('[data-faq-item]');if(add){const container=editor.querySelector('[data-faq-items]');container.insertAdjacentHTML('beforeend',newFaqItemMarkup());updateFaqEditor(editor);setDirty(true);container.querySelector('[data-faq-item]:last-child [data-faq-field="question"]')?.focus();return}if(!item)return;const items=[...editor.querySelectorAll('[data-faq-item]')];const index=items.indexOf(item);if(event.target.closest('[data-faq-remove]'))item.remove();else if(event.target.closest('[data-faq-move="up"]')&&index>0)item.parentElement.insertBefore(item,items[index-1]);else if(event.target.closest('[data-faq-move="down"]')&&index<items.length-1)item.parentElement.insertBefore(items[index+1],item);else return;updateFaqEditor(editor);setDirty(true)})});
    function updateFormLayoutEditor(editor){const items=[...editor.querySelectorAll('[data-form-layout-item]')];const prefix=editor.dataset.layoutName;items.forEach((item,index)=>{const number=index+1;item.querySelector('[data-layout-number]').textContent=number;item.querySelectorAll('[data-layout-field]').forEach(control=>{const field=control.dataset.layoutField;if(control.matches('input[type="checkbox"]')&&((field==='enabled'&&item.dataset.alwaysVisible==='1')||(field==='required'&&item.dataset.alwaysRequired==='1')))return;control.name=`${prefix}[${index}][${field}]`});const enabled=item.querySelector('[data-layout-enabled]');const required=item.querySelector('[data-layout-required]');if(enabled&&required&&item.dataset.alwaysRequired!=='1'){if(!enabled.checked){required.checked=false;required.disabled=true}else required.disabled=false}const up=item.querySelector('[data-layout-move="up"]');const down=item.querySelector('[data-layout-move="down"]');if(up){up.disabled=index===0;up.setAttribute('aria-label',formatCopy(copy.formLayout.move_up,{number}))}if(down){down.disabled=index===items.length-1;down.setAttribute('aria-label',formatCopy(copy.formLayout.move_down,{number}))}})}
    document.querySelectorAll('[data-form-layout-editor]').forEach(editor=>{updateFormLayoutEditor(editor);editor.addEventListener('change',event=>{if(event.target.matches('[data-layout-enabled],[data-layout-required]')){updateFormLayoutEditor(editor);setDirty(true)}});editor.addEventListener('click',event=>{const button=event.target.closest('[data-layout-move]');if(!button)return;const item=button.closest('[data-form-layout-item]');const items=[...editor.querySelectorAll('[data-form-layout-item]')];const index=items.indexOf(item);if(button.dataset.layoutMove==='up'&&index>0)item.parentElement.insertBefore(item,items[index-1]);else if(button.dataset.layoutMove==='down'&&index<items.length-1)item.parentElement.insertBefore(items[index+1],item);else return;updateFormLayoutEditor(editor);setDirty(true)})});
    function previewSettingValue(group,field){const name=`settings[${group}][${field}]`;const checkbox=form?.querySelector(`input[type="checkbox"][name="${name}"]`);if(checkbox)return String(checkbox.checked);return form?.querySelector(`[name="${name}"]:checked`)?.value}
    function applyPreviewMap(root,group,maps){Object.entries(maps).forEach(([field,presets])=>{const variables=presets[previewSettingValue(group,field)];if(!variables)return;Object.entries(variables).forEach(([property,value])=>root.style.setProperty(property,value))})}
    function applyDesignPreview(){try{const root=frame?.contentDocument?.querySelector('[style*="--igf-primary"]');if(!root)return;applyPreviewMap(root,'design',designPreviewMaps);applyPreviewMap(root,'header',headerPreviewMaps);applyPreviewMap(root,'footer',footerPreviewMaps)}catch(error){/* The preview may still be loading. */}}
    function openHashGroup(){const rawHash=window.location.hash.slice(1);if(!rawHash)return;let id;try{id=decodeURIComponent(rawHash)}catch(error){return}const group=document.getElementById(id);if(group?.matches('[data-settings-group]')){group.open=true;group.scrollIntoView({block:'start'})}}
    function setDirty(value = true){dirty=value;status?.classList.remove('is-success','is-error');if(value&&status)status.textContent=copy.unsavedChanges;status?.classList.toggle('is-visible',value);if(saveButton)saveButton.disabled=!value||saving}
    function setNestedValue(target,segments,value){let cursor=target;segments.forEach((segment,index)=>{if(index===segments.length-1){cursor[segment]=value;return}const nextIsIndex=/^\d+$/.test(segments[index+1]);if(!cursor[segment]||typeof cursor[segment]!=='object')cursor[segment]=nextIsIndex?[]:{};cursor=cursor[segment]})}
    function customizerPayload(data){const payload={};const unsafeKeys=new Set(['__proto__','constructor','prototype']);for(const [name,value] of data.entries()){if(name==='_token'||name==='_method'||typeof value!=='string')continue;const segments=name.match(/[^\[\]]+/g);if(segments?.length&&!segments.some(segment=>unsafeKeys.has(segment)))setNestedValue(payload,segments,value)}return payload}
    function showClientErrors(errors,message=copy.saveFailed){if(!clientValidation)return;const list=clientValidation.querySelector('[data-customizer-errors]');const messages=Object.values(errors||{}).flat().filter(value=>typeof value==='string');list.innerHTML=(messages.length?messages:[message]).map(value=>`<li>${escapeHtml(value)}</li>`).join('');clientValidation.hidden=false;clientValidation.focus();clientValidation.scrollIntoView({block:'center'})}
    async function saveCustomizer(event){
        event.preventDefault();
        if(!form||saving)return;
        const data=new FormData(form);const token=String(data.get('_token')||'');let feedbackShown=false;
        clientValidation?.setAttribute('hidden','');saving=true;if(saveButton)saveButton.disabled=true;
        if(status){status.textContent=copy.saving;status.classList.remove('is-success','is-error');status.classList.add('is-visible')}
        try{
            const response=await fetch(form.action,{method:'PUT',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify(customizerPayload(data))});
            const body=await response.json().catch(()=>({}));
            if(!response.ok||!body.global_settings_version){
                let message=copy.serverFailed;let kind='request';
                if(response.status===422){message=copy.saveFailed;kind='validation'}
                else if(response.status===401||response.status===419){message=copy.sessionExpired;kind='session'}
                else if(response.status===403){message=copy.notAllowed;kind='permission'}
                showClientErrors(response.status===422?body.errors:{},message);feedbackShown=true;
                const requestError=new Error(kind);requestError.displayMessage=message;throw requestError;
            }
            const versionField=form.querySelector('[name="global_settings_version"]');if(versionField)versionField.value=body.global_settings_version;
            dirty=false;if(status){status.textContent=copy.saved;status.classList.remove('is-error');status.classList.add('is-visible','is-success')}
            const url=new URL(frame.src);url.searchParams.set('preview',String(Date.now()));frame.src=url.toString();
        }catch(error){
            const message=error.displayMessage||copy.connectionFailed;dirty=true;
            if(status){status.textContent=message;status.classList.remove('is-success');status.classList.add('is-visible','is-error')}
            if(!feedbackShown)showClientErrors({},message);
        }finally{saving=false;if(saveButton)saveButton.disabled=!dirty}
    }
    setDirty(dirty); form?.querySelectorAll('input:not([type=hidden]),textarea,select').forEach(control=>control.addEventListener(control.matches('select,input[type=checkbox],input[type=color],input[type=radio]')?'change':'input',()=>setDirty(true))); const previewsShellSetting=event=>/settings\[(design|header|footer)\]/.test(event.target?.name||''); form?.addEventListener('input',event=>{if(previewsShellSetting(event))applyDesignPreview()}); form?.addEventListener('change',event=>{if(previewsShellSetting(event))applyDesignPreview()}); form?.addEventListener('submit',saveCustomizer); window.addEventListener('beforeunload',event=>{if(!dirty)return;event.preventDefault();event.returnValue=''})
    frame?.addEventListener('load',applyDesignPreview); document.getElementById('customizer-preview-page')?.addEventListener('change',event=>{frame.src=event.target.value}); document.querySelectorAll('[data-preview-width]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-preview-width]').forEach(item=>{const active=item===button;item.classList.toggle('is-active',active);item.setAttribute('aria-pressed',String(active))});frame.style.width=button.dataset.previewWidth})); document.getElementById('refresh-customizer-preview')?.addEventListener('click',()=>{const url=new URL(frame.src);url.searchParams.set('preview',String(Date.now()));frame.src=url.toString()});
    const settingRows=[...document.querySelectorAll('[data-setting-row]')]; const settingGroups=[...document.querySelectorAll('[data-settings-group]')]; const noResults=document.getElementById('customizer-no-results'); document.getElementById('customizer-search')?.addEventListener('input',event=>{const query=event.target.value.trim().toLowerCase();let visibleCount=0;settingRows.forEach(row=>{const visible=!query||row.dataset.search.includes(query);row.hidden=!visible;if(visible)visibleCount+=1});settingGroups.forEach(group=>{const visible=[...group.querySelectorAll('[data-setting-row]')].some(row=>!row.hidden);group.hidden=!visible;if(query&&visible)group.open=true});noResults?.classList.toggle('is-visible',visibleCount===0)});
    function closeMediaPicker(){if(!modal)return;modal.hidden=true;activeMediaInput=null} document.querySelectorAll('[data-media-open]').forEach(button=>button.addEventListener('click',()=>{activeMediaInput=document.getElementById(button.dataset.mediaOpen);modal.hidden=false;mediaSearch.value='';document.querySelectorAll('.media-choice').forEach(choice=>{choice.hidden=false});window.setTimeout(()=>mediaSearch.focus(),20)})); document.querySelectorAll('[data-media-close]').forEach(button=>button.addEventListener('click',closeMediaPicker)); modal?.addEventListener('click',event=>{if(event.target===modal)closeMediaPicker()}); document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal&&!modal.hidden)closeMediaPicker()}); mediaSearch?.addEventListener('input',()=>{const query=mediaSearch.value.trim().toLowerCase();document.querySelectorAll('.media-choice').forEach(choice=>{choice.hidden=Boolean(query)&&!choice.dataset.mediaName.includes(query)})}); document.querySelectorAll('.media-choice').forEach(choice=>choice.addEventListener('click',()=>{if(!activeMediaInput)return;activeMediaInput.value=choice.dataset.mediaUrl;activeMediaInput.dispatchEvent(new Event('input',{bubbles:true}));const preview=document.getElementById(activeMediaInput.id+'-preview');if(preview){preview.src=choice.dataset.mediaUrl;preview.style.visibility='visible'}closeMediaPicker()})); window.addEventListener('hashchange',openHashGroup); openHashGroup();
})();
</script>
@endsection
